/* eslint-disable no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );


// VARIABLES //

var debug = logger( 'plot:view:browser:router' );


// FUNCTIONS //

/**
* Sends a 404 response.
*
* @private
* @param {IncomingMessage} request - HTTP request object
* @param {ServerResponse} response - HTTP response object
*/
function notFound( request, response ) {
	debug( 'Sending 404 response...' );
	response.statusCode = 404;
	response.end();
}


// MAIN //

/**
* Router constructor.
*
* @private
* @constructor
* @returns {Router} router instance
*/
function Router() {
	if ( !( this instanceof Router ) ) {
		return new Router();
	}
	setNonEnumerableReadOnly( this, '_routes', {
		'GET': {},
		'POST': {}
	});
	return this;
}

/**
* Registers a route.
*
* @name route
* @memberof Router.prototype
* @type {Function}
* @param {Object} schema - route schema
* @returns {Router} router instance
*/
setNonEnumerableReadOnly( Router.prototype, 'route', function route( schema ) {
	debug( 'Registering a new route: %s %s', schema.method, schema.url );
	this._routes[ schema.method ][ schema.url ] = schema.handler;
	return this;
});

/**
* Resolves a request handler.
*
* @name resolve
* @memberof Router.prototype
* @type {Function}
* @param {IncomingMessage} request - HTTP request object
* @returns {Function} request handler
*/
setNonEnumerableReadOnly( Router.prototype, 'resolve', function resolve( request ) {
	var method;
	var table;
	var url;
	var fcn;

	method = request.method;
	url = request.url;

	debug( 'Resolving request handler for %s %s', method, url );
	table = this._routes[ method ];
	if ( !table ) {
		debug( 'Unable to resolve request handler.' );
		return notFound;
	}
	fcn = table[ url ];
	if ( !fcn ) {
		debug( 'Unable to resolve request handler.' );
		return notFound;
	}
	debug( 'Successfully resolved request handler.' );
	return fcn;
});


// EXPORTS //

module.exports = Router;
